def normalized_inspected_path(path)
  return '' if path.nil?
  return path if path.empty?
  return path unless defined?(::RuboCop::PathUtil)

  ::RuboCop::PathUtil.smart_path(path)
rescue StandardError
  path
end

def null_device_regexp_match?(value)
  return false if value.nil?
  return false unless value.respond_to?(:match?)

  REGEXP.match?(value)
end

def file_null_correction_source(_node)
  'File::NULL'
end

def array_or_hash_literal_parent?(node)
  parent = node_parent_of(node)
  return false if parent.nil?
  return true if node_has_type?(parent, :array)
  return true if node_has_type?(parent, :hash)
  return true if node_has_type?(parent, :pair)

  false
end

def percent_array_parent?(node)
  parent = node_parent_of(node)
  return false if parent.nil?
  return false unless parent.respond_to?(:percent_literal?)

  parent.percent_literal?
end

def interpolated_string_parent?(node)
  parent = node_parent_of(node)
  return false if parent.nil?

  node_has_type?(parent, :dstr) || node_has_type?(parent, :dsym) || node_has_type?(parent, :xstr)
end

def file_related_send_parent?(node)
  parent = node_parent_of(node)
  return false unless node_has_type?(parent, :send)
  return false unless parent.respond_to?(:method_name)

  %i[open read write binread binwrite foreach readlines empty? exist? size zero? unlink delete].include?(parent.method_name)
end

def kernel_open_parent?(node)
  parent = node_parent_of(node)
  return false unless node_has_type?(parent, :send)
  return false unless parent.respond_to?(:method_name)
  return false unless parent.method_name == :open

  receiver = parent.receiver
  receiver.nil? || (receiver.respond_to?(:const_type?) && receiver.const_type? && receiver.short_name == :URI)
rescue StandardError

